    def change_cable_name(self, current_name, new_name):
        """
        Change name of single cable in inventory. Needs current and new
        cable name as an arguments. Can be used only by Admin user of
        Technician group.

        :param current_name: Current cable name
        :type current_name: str
        :param new_name: New cable name
        :type new_name: str
        :return: {bool, result}
        :rtype: dictionary

        """
        if current_name == new_name:
            msg = f"Cannot change the same names: {current_name} to {new_name}!"
            self.logger.info(msg)
            return {"result": False, "message": msg}

        if self._is_user_technician():
            try:
                cable_to_change, cable_id = self._get_cable_body(current_name)
                if self._execute_cable_update(cable_id,
                                              cable_to_change,
                                              current_name,
                                              new_name):
                    return {"result": True, "message": f"Changed {current_name} to {new_name}."}
            except Exception as e:
                msg = "Cable name change not done! Please verify names or " \
                      f"access level. Current name: {current_name}, new name: {new_name}."
                self.logger.error(f"{msg} {e}")
                return {"result": False, "message": f"Not changed {current_name} to {new_name}."}
        else:
            raise Exception("User doesn't have rights to perform operation!")

    def change_multiple_cable_names(self, cable_names_dict):
        """
        Change name of multiple cables in inventory. Takes a dictionary of pair
        current and new cable name. Example:

        {"current_cable_name": "new_cable_name"}

        Can be used only by Admin user of Technician group.

        :param cable_names_dict: Dictionary of current & new names pairs
        :type cable_names_dict: dict
        :return: {cables names, (bool, result)}
        :rtype: dictionary
        """
        if self._is_user_technician():
            cables_dict = deepcopy(cable_names_dict)
            result = {}
            for key in cables_dict:
                current_name = key
                new_name = cables_dict[key]
                if current_name == new_name:
                    msg = f"Cannot change the same names: {current_name} to {new_name}!"
                    self.logger.info(msg)
                    result[f"{current_name} to {new_name}"] = (False, msg)
                    continue
                try:
                    cable_to_change, cable_id = self._get_cable_body(current_name)
                    if self._execute_cable_update(cable_id,
                                                  cable_to_change,
                                                  current_name,
                                                  new_name):
                        msg = f"Changed: {current_name} to {new_name}."
                        result[f"{current_name} to {new_name}"] = (True, msg)
                    else:
                        msg = f"Not changed: {current_name} to {new_name}."
                        self.logger.info(msg)
                        result[f"{current_name} to {new_name}"] = (False, msg)
                except Exception as e:
                    msg = "Cable name not changed! Please verify names or " \
                          f"access level. Current name: {current_name}, " \
                          f"new name: {new_name}."
                    self.logger.error(f"{msg} {e}")
                    result[f"{current_name} to {new_name}"] = (False, msg)
            return result
        else:
            raise Exception("User doesn't have rights to perform operation!")

    def copy_dropdown_values_to_other_template(self,
                                               from_template_name,
                                               from_property_name,
                                               to_template_name,
                                               to_property_name,
                                               property_group_name,
                                               default=None,
                                               include_current=False,
                                               change_type=False):
        from_template_id = self._get_template_id_by_name(from_template_name)
        from_template_data = self.get_template(from_template_id)
        from_available_values = self._get_dropdown_available_values(from_template_data, from_property_name)
        print(from_available_values)
        if from_available_values != []:
            update_result = self.update_template_dropdown_property_values(
                                                                        template_name=to_template_name,
                                                                        property_group_name=property_group_name,
                                                                        property_name=to_property_name,
                                                                        list_of_values=from_available_values,
                                                                        default=default,
                                                                        include_current=include_current,
                                                                        change_type=change_type)
        else:
            print("No values to update")
            return []
        return update_result

    def update_template_dropdown_property_values(self, template_name,
                                                 property_group_name="",
                                                 property_name="",
                                                 list_of_values=[],
                                                 default=None,
                                                 include_current=False,
                                                 change_type=False):
        """
        Update drop-down values for given template property group property.
        Given list will overwrite previour values

        Only Admin level users

        :param template_name: Template name to be edited
        :type template_name: String
        :param property_group_name: Property Group name where property locate
        :type property_group_name: String
        :param property_name: Name of the property to be edited
        :type property_name: String
        :param list_of_values: List of new values to be updated to drop-down
        :type list_of_values: list
        :param default: Default value for the drop-down
        :type default: String
        :param include_current: If True will keep current values
        :type include_current: Boolean
        :param change_type: If True will change property type to drop-down
        :type change_type: Boolean
        :return: Edited template
        :rtype: json
        """
        if not self._is_user_admin():
            raise Exception("User doesn't have rights to perform operation!")

        template_info = {}
        templates = self.get_templates(filter=f'name::{template_name}')
        for template in templates["templates"]:
            if template["name"] == template_name:
                template_info = template
        if template_info == {}:
            raise Exception("Template not found. Check the name!")
        template_json = self.get_template(template_info["id"])
        property_group_id = ""
        property_info = {}

        for group in template_json["propertyGroups"]:
            if group["name"] == property_group_name:
                property_group_id = group["id"]
                for property in group['properties']:
                    if property["name"] == property_name:
                        property_info = property
                        property_info['defaultValue'] = default
                        if change_type:
                            property_info['type'] = "DROP_DOWN_LIST"
                        if include_current:
                            property_info['availableValues'] = property['availableValues']
                            property_info['availableValues'].extend(list_of_values)
                            property_info['availableValues'] = list(dict.fromkeys(property_info['availableValues']))
                        else:
                            property_info['availableValues'] = list_of_values

        mod_template_body = {
            "propertyGroups": [
                {
                    "id": property_group_id,
                    "properties": [property_info]
                }
            ]
        }
        try:
            update_result = self.update_template(template_info["id"],
                                                 mod_template_body)
        except Exception as e:
            raise Exception(f'Updatating template failed with error: {e}')
        return update_result

    def duplicate_template(self,
                           new_template_name,
                           duplicate_template_name,
                           copy_ports=True):
        """
        Duplicate given template and name it by given new_template_name.
        Can be used to dublicate in same level. From parent template create
        new parent template and from child template a new child template.

        Only Admin level users

        :param new_template_name: Name of the new duplicated template
        :type new_template_name: String
        :param duplicate_template_name: Name of the template to be dublicated
        :type duplicate_template_name: String
        :param copy_ports: Is ports and port groups dublicated
        :type copy_ports: Bool
        :return: Edited template
        :rtype: json
        """
        if not self._is_user_admin():
            raise Exception("User doesn't have rights to perform operation!")

        template_id = self._get_template_id_by_name(duplicate_template_name)
        template_json = self.get_template(template_id)
        new_template = self._edit_template_json(template_json)
        new_template["resource"]["name"] = new_template_name
        # NOT YET SUPPORTED. COME IN VELOCITY API 9.1.x inventory V17
        # "width": template_json["width"],
        # "height": template_json["height"],
        # "fillColour": template_json["fillColour"],
        # "lineColour": template_json["lineColour"],
        try:
            if copy_ports:
                template_result = self.create_template(
                    body=new_template["resource"],
                    copyPortsFrom=template_json["id"])
            else:
                template_result = self.create_template(body=new_template["resource"])
        except Exception as e:
            print(f"Template creation failed: {e}")
        return template_result

    def copy_template_property_group(self, from_template_name,
                                     to_template_name, property_group_name):
        """
        Copy property group and its properties to another template.

        Only Admin level users

        :param from_template_name: Name of the template where to copy
        :type from_template_name: String
        :param to_template_name: Name of the template where to update
        :type to_template_name: String
        :param property_group_name: Name of the template property group
        :type property_group_name: String
        :return: Edited template
        :rtype: json
        """
        if not self._is_user_admin():
            raise Exception("User doesn't have rights to perform operation!")

        from_template_info = {}
        from_templates = self.get_templates(
            filter=f'name::{from_template_name}')
        for template in from_templates["templates"]:
            if template["name"] == from_template_name:
                from_template_info = template
        if from_template_info == {}:
            raise Exception("Template not found. Check the name!")
        from_template_json = self.get_template(from_template_info["id"])

        to_template_info = {}
        to_templates = self.get_templates(filter=f'name::{to_template_name}')
        for template in to_templates["templates"]:
            if template["name"] == to_template_name:
                to_template_info = template
        if to_template_info == {}:
            raise Exception("Template not found. Check the name!")

        new_property_group = []
        for property_group in from_template_json["propertyGroups"]:
            if property_group["name"] == property_group_name:
                del property_group["id"]
                for property in property_group["properties"]:
                    del property["id"]
                    del property["isInherited"]
                new_property_group.append(property_group)

        mod_template_body = {
            "propertyGroups": new_property_group
        }
        try:
            return self.update_template(to_template_info["id"],
                                        mod_template_body)
        except Exception as e:
            print(f"Updatating template failed with error: {e}")

    def export_template_json(self, template_name, copy_ports=False, file_path="C:\\tmp\\"):
        """
        Export template properties to json file. File can be used to import
        to another server using import_template_json.
        - Check that tmp folder exist
        - Check that properties doesn't include hyperlin or document links.
        - Child template doen't need ports if it inherits them from parent

        :param template_name: Name of the template to be exported
        :type template_name: String
        :param file_path: Path where file is saved.
        :type file_path: String
        :retunr: string
        """
        template_id = self._get_template_id_by_name(template_name)
        template_json = self.get_template(template_id)
        template_json = self._edit_template_json(template_json)
        if copy_ports:
            template_json["ports"] = []
            ports_info = self._get_template_ports(template_id)
            port_data_dict = self._get_port_data(ports_info, template_id)
            template_json["ports"] = port_data_dict["ports"]
            template_json["port_templates"] = port_data_dict["port_templates"]
        json_result = json.dumps(template_json, indent=4)
        with open(f'{file_path}{template_name}.json', 'w') as outfile:
            outfile.write(json_result)
        return "Done"

    def import_template_json(self, template_name, parent_name="", file_path="C:\\tmp\\"):
        """
        Import template properties from json file created by
        export_template_json. Can be used to import template to another
        server.
        - If there is parent and child templates, parent must be imported
          first to destination server
        - Parent name is needed to import child templates to correct parent
        - Child doesn't need ports if it inherits them from parent

        :param template_name: Name of the template to be exported
        :type template_name: String
        :param file_path: Path where file is saved.
        :type file_path: String
        :retunr: string
        """
        with open(f'{file_path}{template_name}.json') as json_file:
            import_template = json.load(json_file)

        try:
            if parent_name != "":
                parent_id = self._get_template_id_by_name(parent_name)
                import_template["resource"]["parentId"] = parent_id
            template_result = self.create_template(body=import_template["resource"])
        except Exception as e:
            raise Exception(f"Template creation failed: {e}")
        created_ports = []
        if import_template["ports"] != []:
            port_group_ids_dict = self._create_port_groups(template_id=template_result["id"],
                                                           port_groups_dict=import_template["port_groups"])
            created_template_ports = self.get_template_ports(template_result["id"], limit=200)["ports"]
            port_templates_dict = self._get_templates_info(import_template["port_templates"])
            port_data_body = self._generate_port_data_body(import_template["ports"],
                                                           port_group_ids_dict,
                                                           port_templates_dict,
                                                           created_template_ports,
                                                           template_result["id"])

            if port_data_body != []:
                port_body = {"ports": port_data_body}
                created_ports_data = self.create_template_ports(template_id=template_result["id"],
                                                                body=port_body)
                created_ports = created_ports_data["ports"]

        return {"template": template_result, "ports": created_ports}

    def generate_shelf_list(self, shelf_range, isLRF=False):
        """
        Return list of shelf U places for range.
        Generate four item for one U.
        U01   Whole U-slot
        U01L  Left side of U-slot
        U01R  Right side of U-slot
        U01F  Front of U-slot
        """
        shelf_list = ["None"]
        count = 1
        while count <= shelf_range:
            if count < 10:
                self._add_to_u(shelf_list, count, isLRF, needzero="0")
            else:
                self._add_to_u(shelf_list, count, isLRF)
            count += 1
        return shelf_list

    def dump_yaml_to_file(self, name, topo_yaml, path=None):
        """
            Function to dump topology or reservation yaml to file
            reservation or topology yaml file can be get using:
            get_reservation_yaml(reservation_id)
            get_topology_yaml(topology_id)

            :param name: Name of the file
            :type name: String
            :param topo_yaml: yaml data got from Velocity
            :type topo_yaml: yaml
            :param path: Location for the file
            :type path: String
        """
        if path is None:
            path = rf'C:\tmp\{name}.yaml'
        with open(path, 'w') as outfile:
            yaml.dump(topo_yaml,
                      outfile,
                      default_flow_style=False,
                      sort_keys=False)

    def dump_json_to_file(self, name, json_data, path=None):
        """
            Function to dump topology or reservation yaml to file
            reservation or topology yaml file can be get using:
            get_reservation_yaml(reservation_id)
            get_topology_yaml(topology_id)

            :param name: Name of the file
            :type name: String
            :param topo_yaml: yaml data got from Velocity
            :type topo_yaml: yaml
            :param path: Location for the file ex: C:\tmp
            :type path: String
        """
        if path is None:
            path = rf'C:\tmp\{name}.json'
        else:
            path = rf'{path}\{name}.json'
        with open(path, 'w') as outfile:
            json.dump(json_data,
                      outfile, indent=4)

    def write_to_csv(self, data, file_name, path=""):
        """
        Write data to csv file.
        """
        if path == "":
            location = r'C:\tmp'
        else:
            location = path
        if file_name == "":
            location = location + '\\' + 'data_export.csv'
        else:
            location = location + '\\' + file_name + '.csv'
        with open(location, 'w', newline='') as file:
            csv_rowlist = []
            writer = csv.writer(file)
            csv_rowlist.append(data["properties"])
            csv_rowlist.extend(data["values"])
            writer.writerows(csv_rowlist)
            file.close()
        return 0

