    def copy_topology_folder_to_server(self, to_server: str, from_folder: str, to_folder: str):
        """
            Function to copy topology folder contents from one Velocity server instance to another.
            Creates drafts of the copied topologies with all resources, even if they do not exist on the other server.
            Returns the velocity instance back to the original server after the transfer.
            Requires admin access to the initial server.

            *Velocity server addresses:*

            *Oulu:* velocityoulu.ou.nsn-rdnet.net / 10.35.195.3

            *Oulu Test:* 10.35.195.9

            *Wroclaw:* velocity.wroclaw.nsn-rdnet.net. / 10.42.121.231

            *Hangzhou:* velocity.hz.nsn-rdnet.net

            *Dallas:* velocity.dallas.nsn-rdnet.net


            :param to_server: Server address to which the topologies are transferred to.
            :param from_folder: Topology folder id of the folder that has the topologies to be moved.
            :param to_folder: Destination topology folder on *to_server*.
        """

        if not self._is_user_admin():
            raise Exception("User doesn't have rights to perform operation!")

        original_server = self.get_server_address()
        topo_list = []

        contents = self.get_folder_topologies(from_folder)
        if contents["count"] > 0:
            for topo in contents["topologies"]:
                topology_copy = yaml.safe_load(self.get_topology_yaml(topo["id"]))
                topo_list.append(topology_copy)
        else:
            raise Exception("No topologies in folder to copy!")

        self.set_server_address(to_server)

        try:
            for topo in topo_list:
                self.create_topology_from_yaml(body=topo, folderId=to_folder, isHidden=False)
        except Exception as e:
            raise Exception(f"Error in creating topologies to target folder: {e}")

        self.set_server_address(original_server)
        self.logger.info("Successfully copied topologies to the target server"
                         " and restored connection to the original server")

        return {"status": "SUCCESS"}

    def parent_template_resources_property_value(self, parent_template_name, property_name, path=None, childs=True):
        """
        Function to get wanted property value to json file from child template resources under defined
        parent template. Function go through parent template childs, get devices and parse wanted
        property value to json file.

        default location: C:\tmp folder.

        :param parent_template_name: Name of parent template.
        :param property_name: Name of the property which value is wanted to get.
        :param path: Path to store location. Ex: C:\tmp.
        """
        property_dict = {}
        parent_template = self.get_templates(filter=(f'name::{parent_template_name}'))
        if len(parent_template["templates"]) != 1:
            raise Exception("There is more than one template!")

        if childs is True:
            print("Parent template id: ", parent_template["templates"][0]["id"])
            templates = self.get_templates(filter=(f'parentId::{parent_template["templates"][0]["id"]}'))
            if len(templates["templates"]) == 0:
                raise Exception("There is not any subtemplates!")
        else:
            templates = parent_template
        property_dict["Total"] = len(templates["templates"])
        for template in templates["templates"]:
            result = self._template_resources_self_to_file(template, property_name)
            if result != 0:
                template_name = re.sub('\W+', '-', template["name"])
                property_dict[template_name] = result
            else:
                print(f'Could not find any {property_name} properties')

        file_name = re.sub('\W+', '-', parent_template_name)
        self.dump_json_to_file(f'{file_name}_{property_name}s', property_dict, path)
        return "SUCCESS"

    def get_path_from_devices_port(self, device_name="", device_id="", port_name="", port_id="",
                                   place="", filepath=""):
        """
        Function to get a path of physical connections from given device and port.
        Last device in the path is a device with such first found port that is either not a double-sided port
        or has only one side connected.

        There is option to get the list of physical connections from a file on a computer rather than from
        the database. This is to save time on downloading the data when running the function multiple times in a short
        amount of time.

        In the return there is included interface of the last device so that it could be easily checked if the path is
        correct (does not lead to a patch panel or a hardcoded device).

        Returns:
            path: a list of visited ports, each port represented by a tuple of device name and port name
            last point: dictionary representing last point of the path, with values of its id, name, and interface

        :param device_name: Name of the starting device
        :param device_id: ID of the starting device
        :param port_name: Name of the starting port
        :param port_id: ID of the starting port
        :param place: Starting side of port. Necessary if port is bidirectional. Available values: "FRONT", "BACK" or ""
        :param filepath: Path to a csv file with a list o physical connections. If empty the file would be fetched from
                         the database. Example filepath: C:/tmp/physical_connections.csv
        """

        if place not in ["FRONT", "BACK", ""]:
            raise Exception("VC: Place should be either 'FRONT', 'BACK' or ''")

        if device_name != "":
            device = self.get_devices(filter=f'name::{device_name}')
            if device["total"] != 1:
                raise Exception(f'VC: Problems to find device: {device_name}')
            device = device["devices"][0]
            device_id = device["id"]
        elif device_id != "":
            try:
                device = self.get_device(device_id)
                device_name = device["name"]
            except Exception as e:
                raise Exception(f'VC: Device could not be found: {e}')
        else:
            raise Exception("VC: Device name or id is required!")

        if port_name != "":
            ports = self.get_device_ports(device_id=device_id, filter=f'name::{port_name}')
            if ports["total"] != 1:
                raise Exception(f'VC: Port of name: {port_name} does not belong to device: {device_name}')
        elif port_id != "":
            ports = self.get_device_ports(device_id=device_id, filter=f'id::{port_id}')
            if ports["total"] != 1:
                raise Exception(f'VC: Port of id: {port_id} does not belong to device: {device_name}')
        else:
            raise Exception("VC: Port name or id is required!")

        port = ports["ports"][0]
        if port["connectedPortId"] and port["backConnectedPortId"] and place == "":
            raise Exception('VC: Given port is bidirectional and no side has been chosen as the starting side')

        if port["connectedPortId"] is None and port["backConnectedPortId"] is None:
            raise Exception('VC: Given port is not connected to any other port.')

        connections = []
        if filepath == "":
            # Getting data takes long time. Checks if code can be executed should be before this line
            connections = self._get_physical_connections_list()
        else:
            try:
                with open(filepath, "r") as file:
                    if len(file.readlines()) <= 1:
                        raise Exception(f"VC: The file under the path {filepath} is empty")
                    reader = csv.DictReader(file)
                    for row in reader:
                        connections.append(row)
            except csv.Error as e:
                raise Exception(f"VC: Error reading CSV file: {e} \nThe file was under the path {filepath}")

        path = []
        processed = set()

        path.append((device_name, port_name))
        while True:
            found = False
            for i, row in enumerate(connections):
                if i in processed:
                    continue
                if row['device1'] == device_name and row['port1'] == port_name:
                    if place != "":
                        if row['place1'] != place:
                            continue
                        place = ""
                    device_name = row['device2']
                    port_name = row['port2']
                    path.append((device_name, port_name))
                    processed.add(i)
                    found = True
                    break
                elif row['device2'] == device_name and row['port2'] == port_name:
                    if place != "":
                        if row['place2'] != place:
                            continue
                        place = ""
                    device_name = row['device1']
                    port_name = row['port1']
                    path.append((device_name, port_name))
                    processed.add(i)
                    found = True
                    break
            if not found:
                break

        last_device = self.get_devices(filter=f'name::{device_name}')["devices"][0]
        last_interface = last_device["interface"]
        last_id = last_device["id"]

        if len(path) == 1 and filepath != "":
            self.logger.warning(f"VC: Could not find any connections for {device_name}, please check the file provided "
                                f"is correct. The provided filepath is: {filepath}")

        return {"path": path, "last point": {"id": last_id, "name": device_name, "interface": last_interface}}
